      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-plugin-local-life\",\n  \"version\": \"0.3.2\",\n  \"description\": \"Local-life toolkit for DeepSeek Harness agents: budgets, bill splitting, unit-price comparison with spec normalization, stacked discounts, unit conversions (jin/li/chi, C/F), expense-ledger summaries, loan amortization, recipe costing, and trip checklists\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./local\": \"./lib/local.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\"\n  ],\n  \"scripts\": {\n    \"test\": \"node --test test/\",\n    \"prepublishOnly\": \"node --test test/\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"plugin\",\n    \"bundle\",\n    \"local\",\n    \"life\",\n    \"budget\",\n    \"split\",\n    \"convert\",\n    \"ledger\",\n    \"amortization\",\n    \"loan\",\n    \"shopping\",\n    \"recipe\",\n    \"discount\"\n  ],\n  \"license\": \"MIT\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-fs\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/863683348/dsh-plugin-local-life.git\"\n  },\n  \"homepage\": \"https://github.com/863683348/dsh-plugin-local-life#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/863683348/dsh-plugin-local-life/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  }\n}\n"
